import{_ as e,c as i,o as n,a0 as r}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Structuring Your Practice","description":"Design practice sessions that maximize improvement. Learn how to structure training time for optimal skill development in pétanque.","frontmatter":{"title":"Structuring Your Practice","description":"Design practice sessions that maximize improvement. Learn how to structure training time for optimal skill development in pétanque."},"headers":[],"relativePath":"de/blog/practice-structure.md","filePath":"de/blog/practice-structure.md"}');const t=e({name:"de/blog/practice-structure.md"},[["render",function(e,a,t,l,s,u){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="strukturierung-ihrer-praxis" tabindex="-1">Strukturierung Ihrer Praxis <a class="header-anchor" href="#strukturierung-ihrer-praxis" aria-label="Permalink to &quot;Strukturierung Ihrer Praxis&quot;">​</a></h1><p>Nicht jedes Training ist gleich. Zwei Spieler können die gleiche Zeit auf dem Gelände verbringen und dennoch völlig unterschiedliche Fortschritte erzielen. Der Unterschied liegt oft in der Struktur des Trainings.</p><h2 id="das-problem-mit-unstrukturiertem-training" tabindex="-1">Das Problem mit unstrukturiertem Training <a class="header-anchor" href="#das-problem-mit-unstrukturiertem-training" aria-label="Permalink to &quot;Das Problem mit unstrukturiertem Training&quot;">​</a></h2><p>Die meisten Freizeitaktivitäten sehen folgendermaßen aus:</p><ul><li>Komm vorbei und spiel ein paar Boule-Runden</li><li>Spiele ein paar Gelegenheitsspiele</li><li>Chatte mit Freunden</li><li>Nach Hause gehen</li></ul><p>Das macht zwar Spaß, ist aber für Verbesserungen ineffizient. Ohne Struktur:</p><ul><li>Wiederholen Sie bequeme Muster</li><li>Schwächen vermeiden</li><li>Verpasste Chancen für eine gezielte Entwicklung</li><li>Fortschritt kann nicht verfolgt werden</li></ul><h2 id="grundsatze-effektiver-praxis" tabindex="-1">Grundsätze effektiver Praxis <a class="header-anchor" href="#grundsatze-effektiver-praxis" aria-label="Permalink to &quot;Grundsätze effektiver Praxis&quot;">​</a></h2><h3 id="_1-gezielte-ubung" tabindex="-1">1. Gezielte Übung <a class="header-anchor" href="#_1-gezielte-ubung" aria-label="Permalink to &quot;1. Gezielte Übung&quot;">​</a></h3><p>Jede Sitzung sollte einen klaren Zweck haben:</p><ul><li>Woran arbeite ich heute?</li><li>Wie sieht Erfolg aus?</li><li>Woran werde ich merken, ob ich mich verbessert habe?</li></ul><h3 id="_2-vorsatzliche-schwierigkeit" tabindex="-1">2. Vorsätzliche Schwierigkeit <a class="header-anchor" href="#_2-vorsatzliche-schwierigkeit" aria-label="Permalink to &quot;2. Vorsätzliche Schwierigkeit&quot;">​</a></h3><p>Übung sollte dich herausfordern:</p><ul><li>Arbeite am Rande deiner Fähigkeiten</li><li>Fügen Sie Elemente hinzu, die schwierig sind</li><li>Vermeiden Sie reine Wiederholungen in Ihrer Komfortzone.</li></ul><h3 id="_3-unmittelbares-feedback" tabindex="-1">3. Unmittelbares Feedback <a class="header-anchor" href="#_3-unmittelbares-feedback" aria-label="Permalink to &quot;3. Unmittelbares Feedback&quot;">​</a></h3><p>Sie müssen wissen, wie Sie sich schlagen:</p><ul><li>Ergebnisse der Übungen verfolgen</li><li>Nutzen Sie nach Möglichkeit Videos.</li><li>Holen Sie sich Feedback von Trainingspartnern.</li></ul><h3 id="_4-fokussierte-aufmerksamkeit" tabindex="-1">4. Fokussierte Aufmerksamkeit <a class="header-anchor" href="#_4-fokussierte-aufmerksamkeit" aria-label="Permalink to &quot;4. Fokussierte Aufmerksamkeit&quot;">​</a></h3><p>Qualität vor Quantität:</p><ul><li>Volle Konzentration während des Trainings</li><li>Kürzere, fokussierte Sitzungen sind besser als lange, ablenkende.</li><li>Geistige Beteiligung ist unerlässlich</li></ul><h2 id="sitzungsstruktur" tabindex="-1">Sitzungsstruktur <a class="header-anchor" href="#sitzungsstruktur" aria-label="Permalink to &quot;Sitzungsstruktur&quot;">​</a></h2><h3 id="aufwarmen-10-15-minuten" tabindex="-1">Aufwärmen (10-15 Minuten) <a class="header-anchor" href="#aufwarmen-10-15-minuten" aria-label="Permalink to &quot;Aufwärmen (10-15 Minuten)&quot;">​</a></h3><p><strong>Körperliche Anforderungen:</strong></p><ul><li>Lichtbewegung</li><li>Vorbereitung von Arm und Schulter</li><li>Allmähliche Intensitätssteigerung</li></ul><p><strong>Mental:</strong></p><ul><li>Übergang vom Alltag</li><li>Zielsetzung für die Sitzung</li><li>Beginnen Sie damit, Ihre Aufmerksamkeit zu fokussieren</li></ul><h3 id="technische-arbeit-20-30-minuten" tabindex="-1">Technische Arbeit (20-30 Minuten) <a class="header-anchor" href="#technische-arbeit-20-30-minuten" aria-label="Permalink to &quot;Technische Arbeit (20-30 Minuten)&quot;">​</a></h3><p>Konzentration auf spezifische Fähigkeiten:</p><ul><li>Übung der isolierten Technik</li><li>Übungen zur Schwachstellenanalyse</li><li>Wiederholung mit Aufmerksamkeit</li></ul><p><strong>Beispielhafte Schwerpunkte:</strong></p><ul><li>Zielgenauigkeit auf bestimmte Entfernungen</li><li>Aufnahmen aus verschiedenen Blickwinkeln</li><li>Spezifische Wurfarten (Plombée, Portée usw.)</li></ul><h3 id="angewandte-praxis-20-30-minuten" tabindex="-1">Angewandte Praxis (20-30 Minuten) <a class="header-anchor" href="#angewandte-praxis-20-30-minuten" aria-label="Permalink to &quot;Angewandte Praxis (20-30 Minuten)&quot;">​</a></h3><p>Fähigkeiten in realistischen Kontexten anwenden:</p><ul><li>Simulierte Spielsituationen</li><li>Druckbohrmaschinen</li><li>Entscheidungsfindungspraxis</li></ul><h3 id="abkuhlphase-10-minuten" tabindex="-1">Abkühlphase (10 Minuten) <a class="header-anchor" href="#abkuhlphase-10-minuten" aria-label="Permalink to &quot;Abkühlphase (10 Minuten)&quot;">​</a></h3><p><strong>Körperliche Anforderungen:</strong></p><ul><li>Lichtwurf</li><li>Dehnen</li></ul><p><strong>Mental:</strong></p><ul><li>Wiederholen Sie, was Sie gelernt haben.</li><li>Bereiche für zukünftige Arbeiten notieren</li><li>Übergang aus dem Übungsmodus</li></ul><h2 id="arten-von-ubungseinheiten" tabindex="-1">Arten von Übungseinheiten <a class="header-anchor" href="#arten-von-ubungseinheiten" aria-label="Permalink to &quot;Arten von Übungseinheiten&quot;">​</a></h2><h3 id="kompetenzentwicklungssitzung" tabindex="-1">Kompetenzentwicklungssitzung <a class="header-anchor" href="#kompetenzentwicklungssitzung" aria-label="Permalink to &quot;Kompetenzentwicklungssitzung&quot;">​</a></h3><p>Schwerpunkt: Entwicklung oder Verfeinerung spezifischer Techniken</p><ul><li>70 % technische Übungen</li><li>20 % angewandte Praxis</li><li>10 % Aufwärmen/Abkühlen</li></ul><h3 id="wettbewerbssimulation" tabindex="-1">Wettbewerbssimulation <a class="header-anchor" href="#wettbewerbssimulation" aria-label="Permalink to &quot;Wettbewerbssimulation&quot;">​</a></h3><p>Schwerpunkt: Vorbereitung auf die Spielbedingungen</p><ul><li>20 % Aufwärmen mit einem bestimmten Ziel</li><li>60 % spielähnliches Verhalten mit Druck</li><li>20 % Nachbesprechung und Anpassung</li></ul><h3 id="wartungssitzung" tabindex="-1">Wartungssitzung <a class="header-anchor" href="#wartungssitzung" aria-label="Permalink to &quot;Wartungssitzung&quot;">​</a></h3><p>Fokus: Fähigkeiten auf dem neuesten Stand halten</p><ul><li>Ausgewogene Arbeit in allen Bereichen</li><li>Keine intensive Konzentration auf eine einzige Sache</li><li>Angenehm, aber zielgerichtet</li></ul><h3 id="erholungssitzung" tabindex="-1">Erholungssitzung <a class="header-anchor" href="#erholungssitzung" aria-label="Permalink to &quot;Erholungssitzung&quot;">​</a></h3><p>Fokus: Leichtes Training nach dem Wettkampf</p><ul><li>Niedrige Intensität</li><li>Viel Spaß beim Werfen</li><li>Mentale Neuorientierung</li></ul><h2 id="bohrer-entwerfen" tabindex="-1">Bohrer entwerfen <a class="header-anchor" href="#bohrer-entwerfen" aria-label="Permalink to &quot;Bohrer entwerfen&quot;">​</a></h2><p>Effektive Übungen haben:</p><h3 id="klare-ziele" tabindex="-1">Klare Ziele <a class="header-anchor" href="#klare-ziele" aria-label="Permalink to &quot;Klare Ziele&quot;">​</a></h3><p>Was genau übst du?</p><h3 id="messbare-ergebnisse" tabindex="-1">Messbare Ergebnisse <a class="header-anchor" href="#messbare-ergebnisse" aria-label="Permalink to &quot;Messbare Ergebnisse&quot;">​</a></h3><p>Wie misst man Erfolg?</p><h3 id="angemessene-herausforderung" tabindex="-1">Angemessene Herausforderung <a class="header-anchor" href="#angemessene-herausforderung" aria-label="Permalink to &quot;Angemessene Herausforderung&quot;">​</a></h3><p>Schwer genug, um sich zu dehnen, aber nicht so schwer, dass man es nicht schaffen kann.</p><h3 id="relevanz" tabindex="-1">Relevanz <a class="header-anchor" href="#relevanz" aria-label="Permalink to &quot;Relevanz&quot;">​</a></h3><p>Bezug zu tatsächlichen Spielsituationen</p><h3 id="progression" tabindex="-1">Progression <a class="header-anchor" href="#progression" aria-label="Permalink to &quot;Progression&quot;">​</a></h3><p>Möglichkeiten zur Steigerung des Schwierigkeitsgrades im Laufe der Zeit</p><h2 id="beispielbohrungen" tabindex="-1">Beispielbohrungen <a class="header-anchor" href="#beispielbohrungen" aria-label="Permalink to &quot;Beispielbohrungen&quot;">​</a></h2><h3 id="zielgenauigkeit" tabindex="-1">Zielgenauigkeit <a class="header-anchor" href="#zielgenauigkeit" aria-label="Permalink to &quot;Zielgenauigkeit&quot;">​</a></h3><p><strong>Aufstellung:</strong> Ziel in 8 Metern Entfernung <strong>Ziel:</strong> Innerhalb von 30 cm vom Ziel landen <strong>Erfolgsquote:</strong> Erfolgsquote bei über 20 Würfen <strong>Fortschritt:</strong> Zielgröße verringern, Entfernung erhöhen</p><h3 id="schusskonstanz" tabindex="-1">Schusskonstanz <a class="header-anchor" href="#schusskonstanz" aria-label="Permalink to &quot;Schusskonstanz&quot;">​</a></h3><p><strong>Aufbau:</strong> Stationäre Zielscheibe <strong>Ziel:</strong> Das Tor treffen <strong>Track:</strong> Treffer pro 10 Versuche <strong>Fortschritt:</strong> Winkel variieren, Bewegung hinzufügen</p><h3 id="drucksimulation" tabindex="-1">Drucksimulation <a class="header-anchor" href="#drucksimulation" aria-label="Permalink to &quot;Drucksimulation&quot;">​</a></h3><p><strong>Spielablauf:</strong> Man muss 3 Symbole in einer Reihe erzielen, um zu &quot;gewinnen&quot;. <strong>Ziel:</strong> Vervollständige die Sequenz <strong>Track:</strong> Versuche erforderlich <strong>Fortschritt:</strong> Erhöhung der erforderlichen Sequenz</p><h2 id="wochenplanung" tabindex="-1">Wochenplanung <a class="header-anchor" href="#wochenplanung" aria-label="Permalink to &quot;Wochenplanung&quot;">​</a></h2><h3 id="beispiel-fur-eine-ausgeglichene-woche" tabindex="-1">Beispiel für eine ausgeglichene Woche <a class="header-anchor" href="#beispiel-fur-eine-ausgeglichene-woche" aria-label="Permalink to &quot;Beispiel für eine ausgeglichene Woche&quot;">​</a></h3><p><strong>Montag:</strong> Kompetenzentwicklung (Fokus auf das Zeigen) <strong>Mittwoch:</strong> Wettbewerbssimulation <strong>Freitag:</strong> Fertigkeitsentwicklung (Schwerpunkt Schießen) <strong>Wochenende:</strong> Spielbetrieb</p><h3 id="periodisierung" tabindex="-1">Periodisierung <a class="header-anchor" href="#periodisierung" aria-label="Permalink to &quot;Periodisierung&quot;">​</a></h3><p>Die Intensität im Laufe der Saison variieren:</p><p><strong>Nebensaison:</strong> Intensives Techniktraining <strong>Vorsaison:</strong> Integration und Simulation <strong>Wettkampfsaison:</strong> Wartung und Schärfen <strong>Nachsaison:</strong> Erholung und Reflexion</p><h2 id="haufige-fehler" tabindex="-1">Häufige Fehler <a class="header-anchor" href="#haufige-fehler" aria-label="Permalink to &quot;Häufige Fehler&quot;">​</a></h2><h3 id="zu-viel-spiel" tabindex="-1">Zu viel Spiel <a class="header-anchor" href="#zu-viel-spiel" aria-label="Permalink to &quot;Zu viel Spiel&quot;">​</a></h3><p>Videospiele machen zwar Spaß, zielen aber nicht effizient auf Schwächen ab.</p><h3 id="keine-sendungsverfolgung" tabindex="-1">Keine Sendungsverfolgung <a class="header-anchor" href="#keine-sendungsverfolgung" aria-label="Permalink to &quot;Keine Sendungsverfolgung&quot;">​</a></h3><p>Ohne Messung kann man nicht wissen, ob man sich verbessert.</p><h3 id="schwachen-vermeiden" tabindex="-1">Schwächen vermeiden <a class="header-anchor" href="#schwachen-vermeiden" aria-label="Permalink to &quot;Schwächen vermeiden&quot;">​</a></h3><p>Wir üben naturgemäß das, was wir gut können. Zwingen Sie sich, an Ihren Schwächen zu arbeiten.</p><h3 id="unregelmaßiger-zeitplan" tabindex="-1">Unregelmäßiger Zeitplan <a class="header-anchor" href="#unregelmaßiger-zeitplan" aria-label="Permalink to &quot;Unregelmäßiger Zeitplan&quot;">​</a></h3><p>Unregelmäßiges Üben führt zu unregelmäßigen Ergebnissen.</p><h3 id="keine-mentale-ubung" tabindex="-1">Keine mentale Übung <a class="header-anchor" href="#keine-mentale-ubung" aria-label="Permalink to &quot;Keine mentale Übung&quot;">​</a></h3><p>Körperliche Wiederholung ohne geistige Beteiligung begrenzt den Fortschritt.</p><h2 id="ubungsstab-herstellen" tabindex="-1">Übungsstab herstellen <a class="header-anchor" href="#ubungsstab-herstellen" aria-label="Permalink to &quot;Übungsstab herstellen&quot;">​</a></h2><h3 id="vor-dem-training" tabindex="-1">Vor dem Training <a class="header-anchor" href="#vor-dem-training" aria-label="Permalink to &quot;Vor dem Training&quot;">​</a></h3><ul><li>Setzen Sie klare Ziele</li><li>Bereite dich mental vor</li><li>Notizen der vorherigen Sitzung durchsehen</li></ul><h3 id="wahrend-des-trainings" tabindex="-1">Während des Trainings <a class="header-anchor" href="#wahrend-des-trainings" aria-label="Permalink to &quot;Während des Trainings&quot;">​</a></h3><ul><li>Bleib konzentriert</li><li>Ergebnisse der Rennstrecke</li><li>Bei Bedarf anpassen</li></ul><h3 id="nach-dem-training" tabindex="-1">Nach dem Training <a class="header-anchor" href="#nach-dem-training" aria-label="Permalink to &quot;Nach dem Training&quot;">​</a></h3><ul><li>Notieren Sie, was Sie gelernt haben.</li><li>Nächste Schritte identifizieren</li><li>Den Fortschritt feiern</li></ul><h2 id="der-10-000-stunden-mythos" tabindex="-1">Der 10.000-Stunden-Mythos <a class="header-anchor" href="#der-10-000-stunden-mythos" aria-label="Permalink to &quot;Der 10.000-Stunden-Mythos&quot;">​</a></h2><p>Es geht nicht nur um die Stunden – es geht um die Qualität. 1.000 Stunden gezieltes Üben sind besser als 10.000 Stunden gedankenloses Wiederholen.</p><p>Wenn du dein Training zielgerichtet gestaltest, zählt jede Stunde mehr.</p><hr><p>| <em>Verwandt: <a href="/en/education/training/">Trainingsmethoden</a> | <a href="/en/education/training/drills">Trainingsübungen</a> | <a href="/en/education/goals/">Zielsetzung</a></em> |</p>',100)])])}]]);export{a as __pageData,t as default};
